\usepackage{tkz-euclide}
\usepackage{ifthen}
\usetkzobj{all}
\newcommand{\myfraclengthf}[3]{
    \pgfmathifisint{#1}{#1}{
        \if {\pgfmathparse{#3 == 0}}{ 
            \dfrac{ \pgfmathparse{int(#1*#2)}\pgfmathresult }{ #2 }
            }
        \else {
            \pgfmathparse{int(#1)}\pgfmathresul\dfrac{\pgfmathparse{int(#1*#2)-int(#1)*#2}\pgfmathresult}{#2}
        }
    }
}

\newcommand{\myfraclength}[3]{
        \pgfmathparse{(#1)}\pgfmathresul  \dfrac{\pgfmathparse{int(#1*#2)-int(#1)*#2}\pgfmathresult}{#2}
}

\newcommand{\myrecprism}[9]{
		\coordinate (A) at (0,0,0);
		\coordinate (B) at (#1,0,0);
		\coordinate (C) at (#1,0,-#2);
		\coordinate (D) at (0,0,-#2);
		\coordinate (E) at (0,#3,0);
		\coordinate (F) at (#1,#3,0);
		\coordinate (H) at (0,#3,-#2);
		\coordinate (G) at (#1,#3,-#2);

		\tkzDrawPolygon[very thick, color=#4, fill=#4!15, fill opacity=#5](A,B,C,G,H,E,A)
        \tkzDrawSegments[very thick, color=#4](E,F B,F G,F)
		\tkzDrawSegments[thin, color=#4, dashed](A,D H,D C,D)

		\tkzLabelSegment[below](A,B){\small #7$\:\text{#6}$}
		\tkzLabelSegment[below right](C,B){\small #8$\:\text{#6}$}
		\tkzLabelSegment[right](G,C){\small#9$\:\text{#6}$}

